entries[18647] = { ["name"] = "Verbannen", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerbannt das feindliche Ziel und verhindert damit jegliche Aktion, macht es aber bis zu 30 sec lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden. Wird 'Verbannung' auf ein verbanntes Ziel gewirkt, wird die Verbannung beendet. Funktioniert nur bei Dämonen und Elementaren." }
entries[18649] = { ["name"] = "Schattenschuss", ["text"] = "5 - 30 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nSchießt auf einen Feind, verursacht Schattenschaden." }
