entries[18657] = { ["name"] = "Winterschlaf", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nZwingt das feindliche Ziel bis zu 30 sec lang zu schlafen. Jeglicher Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Winterschlaf versetzt werden. Funktioniert nur bei Wildtieren und Drachkin." }
